with scored as (select *, ntile(4) over (partition by supplier_id, category order by stock_qty desc, id) as stock_qty_bucket, last_value(price) ignore nulls over w_ordered as last_known_price, corr(price, cost) over w_recent as corr_price_cost from products window w_ordered as (partition by category, brand order by price, id rows between unbounded preceding and current row), w_recent as (partition by brand)) select s.id, s.category, s.stock_qty, s.launch_date, s.tags, s.supplier_id, s.stock_qty_bucket, s.last_known_price, s.corr_price_cost, case when category rlike '^(Electronics|Sports)$' then 'CORE' when category rlike '^(Home|Books)$' then 'PRIORITY' else 'GROUP_B' end as category_zone, (select max(x.price) from products x where x.supplier_id = s.supplier_id) as max_product_price from scored s order by id desc nulls last;
